import 'dart:ui' show Locale;

import '../services/office_document_service.dart';
import 'portable_office_preview_strings.dart';
import 'legacy_word_preview_strings.dart';
import 'word_format_strings.dart';

/// Translates only messages marked as generated by the document parser.
class OfficePreviewStrings {
  OfficePreviewStrings(Locale locale)
    : _values = _translations[locale.languageCode] ?? _translations['en']!,
      _word = WordFormatStrings(locale),
      _legacyWord = LegacyWordPreviewStrings(locale),
      _portable = PortableOfficePreviewStrings(locale);

  final List<String> _values;
  final WordFormatStrings _word;
  final LegacyWordPreviewStrings _legacyWord;
  final PortableOfficePreviewStrings _portable;

  static const _headingLabels = {
    'en': ['Sheet', 'Slide'],
    'de': ['Tabelle', 'Folie'],
    'fr': ['Feuille', 'Diapositive'],
    'es': ['Hoja', 'Diapositiva'],
    'pt': ['Folha', 'Diapositivo'],
    'zh': ['工作表', '幻灯片'],
    'ja': ['シート', 'スライド'],
    'ko': ['시트', '슬라이드'],
    'ar': ['ورقة', 'شريحة'],
  };

  String headings(
    String input,
    List<OfficeGeneratedHeading> headings,
    Locale locale,
  ) {
    final labels = _headingLabels[locale.languageCode] ?? _headingLabels['en']!;
    var result = input;
    for (final heading in headings.reversed) {
      final label = labels[heading.kind == OfficeHeadingKind.sheet ? 0 : 1];
      result = result.replaceRange(
        heading.start,
        heading.end,
        '$label ${heading.number}',
      );
    }
    return result;
  }

  String text(OfficeDocument document) => switch (document.fallback) {
    OfficePreviewFallback.legacyPresentation => _values[0],
    OfficePreviewFallback.extractionFailed => _values[2],
    OfficePreviewFallback.missingDocx =>
      _values[3]
          .replaceAll('{file}', 'document.xml')
          .replaceAll('{format}', 'DOCX'),
    OfficePreviewFallback.missingOds => _missing('ODS'),
    OfficePreviewFallback.missingOdp => _missing('ODP'),
    OfficePreviewFallback.missingOdt => _missing('ODT'),
    null => switch (document.legacyWordPreview) {
      final preview? => _legacyWord.text(preview),
      null => document.plainText,
    },
  };

  String? safeHtml(OfficeDocument document) =>
      switch (document.legacyWordPreview) {
        final preview? => _legacyWord.html(preview),
        null => document.safeHtml,
      };

  String get searchLimit => _legacyWord.searchLimit;
  String get searchedPreview => _legacyWord.searchedPreview;
  String get textLimit => _legacyWord.textLimit;

  String _missing(String format) => _values[3]
      .replaceAll('{file}', 'content.xml')
      .replaceAll('{format}', format);

  String? note(OfficeDocument document) {
    if (document.notice case final notice?) return _portable.notice(notice);
    if (document.fallback == OfficePreviewFallback.legacyPresentation)
      return _values[1];
    final note = document.note;
    return note == null ? null : _word.translate(note) ?? note;
  }

  static const Map<String, List<String>> _translations = {
    'en': [
      '(Legacy PowerPoint (.ppt) files cannot be rendered inline. Use the system preview (Quick Look) button on macOS/iOS, or save the file as .pptx.)',
      'Legacy .ppt format is not supported; Hex view is available.',
      '(Could not extract text from this document)',
      '(No {file} found in this {format})',
    ],
    'de': [
      '(Ältere PowerPoint-Dateien (.ppt) können nicht direkt angezeigt werden. Verwenden Sie auf macOS/iOS die Systemvorschau (Quick Look) oder speichern Sie die Datei als .pptx.)',
      'Das ältere .ppt-Format wird nicht unterstützt; die Hex-Ansicht ist verfügbar.',
      '(Text konnte nicht aus diesem Dokument extrahiert werden)',
      '({file} wurde in dieser {format}-Datei nicht gefunden)',
    ],
    'fr': [
      '(Les anciens fichiers PowerPoint (.ppt) ne peuvent pas être affichés ici. Utilisez l’aperçu système (Quick Look) sur macOS/iOS ou enregistrez le fichier au format .pptx.)',
      'L’ancien format .ppt n’est pas pris en charge ; la vue hexadécimale est disponible.',
      '(Impossible d’extraire le texte de ce document)',
      '({file} introuvable dans ce fichier {format})',
    ],
    'es': [
      '(Los archivos antiguos de PowerPoint (.ppt) no se pueden mostrar aquí. Use la vista previa del sistema (Quick Look) en macOS/iOS o guarde el archivo como .pptx.)',
      'El formato antiguo .ppt no es compatible; la vista hexadecimal está disponible.',
      '(No se pudo extraer el texto de este documento)',
      '(No se encontró {file} en este archivo {format})',
    ],
    'pt': [
      '(Os ficheiros antigos do PowerPoint (.ppt) não podem ser apresentados aqui. Utilize a pré-visualização do sistema (Quick Look) no macOS/iOS ou guarde o ficheiro como .pptx.)',
      'O formato antigo .ppt não é suportado; a vista hexadecimal está disponível.',
      '(Não foi possível extrair o texto deste documento)',
      '({file} não encontrado neste ficheiro {format})',
    ],
    'zh': [
      '（无法直接显示旧版 PowerPoint（.ppt）文件。请在 macOS/iOS 上使用系统预览（快速查看），或将文件保存为 .pptx。）',
      '不支持旧版 .ppt 格式；可以使用十六进制视图。',
      '（无法提取此文档中的文本）',
      '（此 {format} 文件中未找到 {file}）',
    ],
    'ja': [
      '（古い PowerPoint（.ppt）ファイルはここに表示できません。macOS/iOS ではシステムプレビュー（クイックルック）を使用するか、ファイルを .pptx 形式で保存してください。）',
      '古い .ppt 形式には対応していません。16進数表示を使用できます。',
      '（この文書からテキストを抽出できませんでした）',
      '（この {format} に {file} が見つかりません）',
    ],
    'ko': [
      '(이전 PowerPoint(.ppt) 파일은 여기에서 표시할 수 없습니다. macOS/iOS에서 시스템 미리보기(훑어보기)를 사용하거나 파일을 .pptx로 저장하세요.)',
      '이전 .ppt 형식은 지원되지 않으며 16진수 보기를 사용할 수 있습니다.',
      '(이 문서에서 텍스트를 추출할 수 없습니다)',
      '(이 {format}에서 {file}을 찾을 수 없습니다)',
    ],
    'ar': [
      '(لا يمكن عرض ملفات PowerPoint القديمة ‏(.ppt) هنا. استخدم معاينة النظام (Quick Look) على macOS/iOS أو احفظ الملف بصيغة .pptx.)',
      'صيغة .ppt القديمة غير مدعومة؛ يتوفر العرض السداسي عشري.',
      '(تعذر استخراج النص من هذا المستند)',
      '(لم يُعثر على {file} في ملف {format} هذا)',
    ],
  };
}
